from sqlalchemy import Column, Integer, String, DateTime, ForeignKey, Enum, Text, UniqueConstraint
from sqlalchemy.dialects import mysql
from sqlalchemy.orm import declarative_base
from sqlalchemy.sql import func
from .users import Base
class Enquiry(Base): __tablename__ = "enquiries"; id = Column(mysql.BIGINT(unsigned=True), primary_key=True, autoincrement=True); property_listing_id = Column(mysql.BIGINT(unsigned=True), ForeignKey("property_listings.id", ondelete="CASCADE", onupdate="CASCADE"), nullable=False); buyer_user_id = Column(mysql.BIGINT(unsigned=True), ForeignKey("users.id", ondelete="CASCADE", onupdate="CASCADE"), nullable=False); owner_user_id = Column(mysql.BIGINT(unsigned=True), ForeignKey("users.id", ondelete="CASCADE", onupdate="CASCADE"), nullable=False); message = Column(Text, nullable=True); status = Column(Enum("NEW","CONTACTED","CLOSED"), nullable=False, server_default="NEW"); closing_reason = Column(String(500), nullable=True)
class ActiveEnquiry(Base): __tablename__ = "active_enquiries"; id = Column(mysql.BIGINT(unsigned=True), primary_key=True, autoincrement=True); enquiry_id = Column(mysql.BIGINT(unsigned=True), ForeignKey("enquiries.id", ondelete="CASCADE", onupdate="CASCADE"), nullable=False); buyer_user_id = Column(mysql.BIGINT(unsigned=True), ForeignKey("users.id", ondelete="CASCADE", onupdate="CASCADE"), nullable=False); property_listing_id = Column(mysql.BIGINT(unsigned=True), ForeignKey("property_listings.id", ondelete="CASCADE", onupdate="CASCADE"), nullable=False); started_at = Column(DateTime, server_default=func.current_timestamp(), nullable=False); __table_args__ = (UniqueConstraint("buyer_user_id","property_listing_id", name="uk_active_buyer_listing"),)